import * as THREE from 'three/webgpu';
import { color, uniform, mix, positionLocal, clamp } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.userData.handlers = {};

  const timelines = [];
  const toDispose = [];

  // Dimensions and colors
  const W = 3.4, H = 1.9;
  const C = {
    gradStart: '#1a1a22',
    gradEnd: '#111116',
    border: '#26262f',
    accent: '#ff2a38',
    text: '#e8ecf2',
  };

  // ===== PANEL =====
  const panelGeo = new THREE.PlaneGeometry(W, H);
  toDispose.push(panelGeo);

  const panelMat = new THREE.MeshStandardNodeMaterial({
    colorNode: mix(
      color(new THREE.Color(C.gradEnd)),
      color(new THREE.Color(C.gradStart)),
      clamp(positionLocal.y / (H / 2), uniform(0), uniform(1))
    ),
    roughnessNode: uniform(0.6),
    metalnessNode: uniform(0.2),
    clearcoatNode: uniform(0.1),
  });
  toDispose.push(panelMat);

  const panelMesh = new THREE.Mesh(panelGeo, panelMat);
  panelMesh.position.z = 0;
  group.add(panelMesh);

  // ===== QUOTATION MARK =====
  let quoteMark = null;
  if (ctx.fontAtlas) {
    try {
      quoteMark = ctx.fontAtlas({
        text: '"',
        fontSize: 62,
        fontFamily: 'Lora',
        fontWeight: 600,
        color: C.accent,
      });
      if (quoteMark) {
        quoteMark.position.set(-W / 2 + 0.5, H / 2 - 0.5, 0.02);
        quoteMark.scale.set(1.04, 1.04, 1.04);
        group.add(quoteMark);

        // Extrusion depth simulation
        const quoteMarkBack = quoteMark.clone();
        quoteMarkBack.position.z = 0.02 - 0.04;
        if (quoteMarkBack.material) {
          quoteMarkBack.material = quoteMarkBack.material.clone();
          quoteMarkBack.material.opacity = 0.35;
        }
        group.add(quoteMarkBack);
      }
    } catch (e) {
      // fontAtlas unavailable
    }
  }

  // ===== QUOTE TEXT =====
  let quoteTxt = null;
  if (ctx.fontAtlas) {
    try {
      quoteTxt = ctx.fontAtlas({
        text: "The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.",
        fontSize: 20,
        fontFamily: 'Lora',
        fontWeight: 400,
        color: C.text,
        maxWidth: 2.4,
        lineHeight: 1.45,
      });
      if (quoteTxt) {
        quoteTxt.position.set(-W / 2 + 0.5, -0.1, 0.03);
        group.add(quoteTxt);
      }
    } catch (e) {
      // fontAtlas unavailable
    }
  }

  // ===== ACCENT RULE =====
  const ruleGeo = new THREE.PlaneGeometry(0.2, 0.02);
  toDispose.push(ruleGeo);

  const ruleMat = new THREE.MeshBasicNodeMaterial({
    colorNode: color(new THREE.Color(C.accent)),
  });
  toDispose.push(ruleMat);

  const ruleMesh = new THREE.Mesh(ruleGeo, ruleMat);
  ruleMesh.position.set(-W / 2 + 0.5, -H / 2 + 0.32, 0.03);
  group.add(ruleMesh);

  // ===== ATTRIBUTION =====
  let attribution = null;
  if (ctx.fontAtlas) {
    try {
      attribution = ctx.fontAtlas({
        text: "M. OKAFOR",
        fontSize: 13,
        fontFamily: 'JetBrains Mono',
        fontWeight: 700,
        color: C.text,
        letterSpacing: 0.08,
      });
      if (attribution) {
        attribution.position.set(-W / 2 + 0.8, -H / 2 + 0.32, 0.03);
        group.add(attribution);
      }
    } catch (e) {
      // fontAtlas unavailable
    }
  }

  // ===== CAPTION =====
  let caption = null;
  if (ctx.fontAtlas) {
    try {
      caption = ctx.fontAtlas({
        text: "COLLECTOR SINCE 2019",
        fontSize: 9,
        fontFamily: 'JetBrains Mono',
        fontWeight: 400,
        color: C.text,
        letterSpacing: 0.12,
      });
      if (caption) {
        caption.position.set(-W / 2 + 0.8, -H / 2 + 0.15, 0.03);
        group.add(caption);
      }
    } catch (e) {
      // fontAtlas unavailable
    }
  }

  // ===== INITIAL ANIMATION STATE =====
  group.position.y += 0.2;
  group.traverse((child) => {
    if (child.material && child !== panelMesh) {
      child.material.transparent = true;
      child.material.opacity = 0;
    }
  });

  // ===== ANIMATIONS =====
  // Fade-up: panel position and child opacity
  const fadeUpTl = gsap.timeline();
  fadeUpTl.to(group.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0);

  group.children.forEach((child) => {
    if (child.material && child !== panelMesh) {
      fadeUpTl.to(child.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
    }
  });
  timelines.push(fadeUpTl);

  // Weighted-settle: quote mark scale
  if (quoteMark) {
    const settleTl = gsap.timeline();
    settleTl.to(quoteMark.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out',
      delay: 0.5,
    });
    timelines.push(settleTl);
  }

  // ===== CLEANUP =====
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    gsap.killTweensOf([group.position]);
    if (quoteMark && quoteMark.scale) {
      gsap.killTweensOf(quoteMark.scale);
    }
    toDispose.forEach((d) => d.dispose());
    group.children.forEach((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
  };

  return group;
}
